-- ==============================================================================
-- FraudGuard Database Migration V5: Suspicious Activity Reports (SAR) (MySQL)
-- Compliance reports generated by Gemini AI for FinCEN reporting
-- ==============================================================================

CREATE TABLE sar_reports (
  id                 VARCHAR(36) PRIMARY KEY,
  transaction_id     VARCHAR(36) NOT NULL,
  generated_by       VARCHAR(36) NOT NULL,
  report_text        LONGTEXT NOT NULL,
  model_used         VARCHAR(100) NOT NULL DEFAULT 'gemini-2.0-flash',
  prompt_token_count INT,
  output_token_count INT,
  generation_ms      BIGINT,
  status             VARCHAR(30) NOT NULL DEFAULT 'DRAFT'
                     CHECK (status IN ('DRAFT','FINAL','FILED')),
  filed_at           DATETIME(6),
  filed_by           VARCHAR(36),
  notes              TEXT,
  created_at         DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  updated_at         DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6),
  CONSTRAINT fk_sar_txn FOREIGN KEY (transaction_id) REFERENCES transactions(id) ON DELETE RESTRICT,
  CONSTRAINT fk_sar_gen FOREIGN KEY (generated_by) REFERENCES users(id) ON DELETE RESTRICT,
  CONSTRAINT fk_sar_filed_by FOREIGN KEY (filed_by) REFERENCES users(id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE INDEX idx_sar_transaction  ON sar_reports(transaction_id);
CREATE INDEX idx_sar_generated_by ON sar_reports(generated_by);
CREATE INDEX idx_sar_status       ON sar_reports(status);
CREATE INDEX idx_sar_created      ON sar_reports(created_at DESC);
